#### Example 1: Routing Layer (Nginx)

```nginx
# Route traffic between ASP.NET and React based on feature flags

upstream aspnet_backend {
    server iis-server.internal:80;
}

upstream react_backend {
    server cloudfront.amazonaws.com:443;
}

server {
    listen 443 ssl;
    server_name enterprise.gainwell.com;

    location /claims/search {
        # Check feature flag via internal API
        auth_request /feature-flag-check?route=claims-search;

        # If feature flag enabled, route to React (CloudFront)
        error_page 200 = @react_app;

        # Otherwise route to ASP.NET (IIS)
        error_page 404 = @aspnet_app;
    }

    location @react_app {
        proxy_pass https://react_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }

    location @aspnet_app {
        proxy_pass http://aspnet_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
    }
}
```

