[patterns/application/micro-frontend/PTN-APP-MFE-013-aspnet-to-react-migration-pattern.md#example-2-react-component-replacing-telerik-grid]

#### Example 2: React Component Replacing Telerik Grid

```typescript
// Before: Telerik ASP.NET Server Control
// <telerik:RadGrid ID="ClaimsGrid" runat="server" />

// After: React Component
import { Table, Column } from '@gainwell/design-system';
import { useClaims } from '../hooks/useClaims';

export function ClaimsGrid() {
  const { claims, loading, error } = useClaims();

  if (loading) return <LoadingSpinner />;
  if (error) return <ErrorMessage error={error} />;

  return (
    <Table
      data={claims}
      sortable
      filterable
      paginated
      pageSize={25}
      ariaLabel="Claims listing"
    >
      <Column field="claimId" header="Claim ID" sortable />
      <Column field="memberId" header="Member ID" />
      <Column
        field="amount"
        header="Amount"
        formatter={(value) => formatCurrency(value)}
      />
      <Column field="status" header="Status" />
      <Column
        field="actions"
        header="Actions"
        render={(row) => (
          <Button onClick={() => viewClaim(row.claimId)}>
            View Details
          </Button>
        )}
      />
    </Table>
  );
}
```

