#### Example 3: Backend API Extraction

```csharp
// Before: ASP.NET Code-Behind
protected void Page_Load(object sender, EventArgs e) {
    var claimId = Request.QueryString["claimId"];
    var claim = claimService.GetClaim(claimId);
    ClaimIdLabel.Text = claim.ClaimId;
    AmountLabel.Text = claim.Amount.ToString("C");
}

// After: ASP.NET Core Web API
[ApiController]
[Route("api/v1/claims")]
public class ClaimsController : ControllerBase {
    private readonly IClaimService _claimService;

    public ClaimsController(IClaimService claimService) {
        _claimService = claimService;
    }

    [HttpGet("{claimId}")]
    [Authorize]
    [ProducesResponseType(typeof(ClaimDto), 200)]
    [ProducesResponseType(404)]
    public async Task<IActionResult> GetClaim(string claimId) {
        var claim = await _claimService.GetClaimAsync(claimId);

        if (claim == null) {
            return NotFound(new { message = $"Claim {claimId} not found" });
        }

        // Audit log for HIPAA compliance
        await _auditService.LogAccessAsync(
            User.Identity.Name,
            "VIEW_CLAIM",
            claimId
        );

        return Ok(claim);
    }
}
```
